import{c as l,J as r,h as o,k as e}from"./chunks/framework.WgZQdPFo.js";const p=JSON.parse('{"title":"Витрина и интернет-магазин мастера","description":"Автономный генератор статического интернет-магазина (Jamstack SSG), дизайн «Деликатный премиум», единый стол заказов и публикация сайта в ОмниКрафт ЕРП.","frontmatter":{"title":"Витрина и интернет-магазин мастера","description":"Автономный генератор статического интернет-магазина (Jamstack SSG), дизайн «Деликатный премиум», единый стол заказов и публикация сайта в ОмниКрафт ЕРП.","order":9},"headers":[],"relativePath":"ru/docs/spaces/production/web-store.md","filePath":"ru/docs/spaces/production/web-store.md"}'),s={name:"ru/docs/spaces/production/web-store.md"};function i(n,t,a,g,d,c){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="витрина-и-интернет-магазин-мастера" tabindex="-1">Витрина и интернет-магазин мастера <a class="header-anchor" href="#витрина-и-интернет-магазин-мастера" aria-label="Permalink to &quot;Витрина и интернет-магазин мастера&quot;">​</a></h1><p>Встроенный модуль <strong>«Витрина»</strong> превращает базу рецептов, складских остатков и фотографий изделий в автономный, быстрый и современный интернет-магазин без абонентской платы за конструкторы сайтов и без уязвимых серверных систем управления контентом.</p><p>Витрина создается по технологии статической генерации (Jamstack SSG): на выходе получается чистый набор автономных файлов (HTML, стили CSS, скрипты на чистом JavaScript и оптимизированные изображения). Такой сайт открывается мгновенно на смартфонах и компьютерах, не требует настройки баз данных на хостинге и может бесплатно размещаться на ГитХабе, в объектных хранилищах (S3) или на традиционном хостинге по протоколу передачи файлов (FTP).</p><hr><h2 id="архитектура-и-возможности-версии-v3" tabindex="-1">Архитектура и возможности версии v3 <a class="header-anchor" href="#архитектура-и-возможности-версии-v3" aria-label="Permalink to &quot;Архитектура и возможности версии v3&quot;">​</a></h2><p>Витрина нового поколения объединяет эстетику авторского ремесла с инженерной надежностью:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Подсистема</th><th style="text-align:left;">Назначение в программе</th><th style="text-align:left;">Польза для мастерской</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Дизайн «Деликатный премиум»</strong></td><td style="text-align:left;">Автономная типографика Inter WOFF2, латунные акценты, светлая и тёмная темы оформления</td><td style="text-align:left;">Премиальный вид авторских изделий без зависимости от внешних шрифтовых серверов</td></tr><tr><td style="text-align:left;"><strong>Многостраничная структура</strong></td><td style="text-align:left;">Главная страница с витриной, каталог с фильтрами, страницы товаров, разделы доставки и блог</td><td style="text-align:left;">Полноценный сайт мастерской вместо простого одностраничного прайс-листа</td></tr><tr><td style="text-align:left;"><strong>Модульные карточки изделий</strong></td><td style="text-align:left;">Конструктор блоков описания: вводный текст, сетка преимуществ, история мастера, видео, таблица свойств, частые вопросы</td><td style="text-align:left;">Убедительная подача штучных и серийных изделий с акцентом на качество материалов</td></tr><tr><td style="text-align:left;"><strong>Суверенный чекаут и 152-ФЗ</strong></td><td style="text-align:left;">Прямой заказ в Телеграм и Ватсап, локальный скрипт <code>order.php</code> или формы, согласие на обработку данных</td><td style="text-align:left;">100% соответствие законодательству РФ о защите персональных данных без риска блокировок</td></tr><tr><td style="text-align:left;"><strong>Встроенный предпросмотр</strong></td><td style="text-align:left;">Локальный многопоточный сервер с защитой от кэширования для моментальной проверки</td><td style="text-align:left;">Оценка витрины в реальном браузере до выгрузки на рабочий хостинг</td></tr><tr><td style="text-align:left;"><strong>Транспорт публикации</strong></td><td style="text-align:left;">Локальная папка / ZIP-архив, протокол FTP, облачные хранилища S3 (Яндекс Облако), страницы ГитХаб</td><td style="text-align:left;">Выгрузка обновлений за пару секунд благодаря сверке контрольных сумм SHA-256</td></tr><tr><td style="text-align:left;"><strong>Единый стол заказов</strong></td><td style="text-align:left;">Централизованный сбор входящих заявок, умная вставка из буфера, быстрые ответы и списание остатков по ФИФО</td><td style="text-align:left;">Исключение ошибок ручного учета и оперативное ведение диалога с заказчиком</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Автономия от чужих серверов</p><p>В отличие от облачных конструкторов сайтов, витрина <strong>«ОмниКрафт ЕРП»</strong> не заблокируется из-за санкций, не списывает регулярную абонентскую плату и не внедряет чужую рекламу. Все исходные данные хранятся на вашем компьютере, а опубликованный сайт принадлежит только вам.</p></div><hr><h2 id="устроиство-витрины-мастера" tabindex="-1">Устройство витрины мастера <a class="header-anchor" href="#устроиство-витрины-мастера" aria-label="Permalink to &quot;Устройство витрины мастера&quot;">​</a></h2><h3 id="_1-главная-страница-и-витрина-изделии" tabindex="-1">1. Главная страница и витрина изделий <a class="header-anchor" href="#_1-главная-страница-и-витрина-изделии" aria-label="Permalink to &quot;1. Главная страница и витрина изделий&quot;">​</a></h3><p>Главная страница знакомит посетителя с ремеслом и сразу демонстрирует знаковые работы:</p><ul><li><strong>Трехчастный промо-блок (Triptych Hero):</strong> объединяет ёмкое торговое предложение мастерской, фото флагманского изделия и три карточки ключевых достоинств (например, ручной седельный шов, натуральное дубление, пожизненная гарантия).</li><li><strong>Витрина избранных работ:</strong> подборка изделий с контрастными бейджами («Хит», «Новинка», «Под заказ», «В наличии»).</li><li><strong>Блок «Слово мастера»:</strong> авторская колонка с фотографией ремесленника, цитатой о подходе к труду и подписью, формирующая доверие покупателя.</li></ul><h3 id="_2-карточка-изделия-и-модульные-секции" tabindex="-1">2. Карточка изделия и модульные секции <a class="header-anchor" href="#_2-карточка-изделия-и-модульные-секции" aria-label="Permalink to &quot;2. Карточка изделия и модульные секции&quot;">​</a></h3><p>Страница изделия спроектирована по двухколоночной схеме:</p><ul><li><strong>Левая колонка:</strong> интерактивная фотогалерея с поддержкой свайпов на сенсорных экранах и модульный стек информационных блоков.</li><li><strong>Правая плавающая панель:</strong> всегда остается перед глазами при прокрутке. Содержит точную цену, выбор модификаций (цвет, размер), счетчик тиража, статус складского остатка, кнопку добавления в корзину и прямые ссылки для быстрой консультации в Телеграм и Ватсап.</li><li><strong>Нижняя мобильная панель покупки:</strong> на экранах смартфонов фиксируется внизу экрана, позволяя купить изделие без долгого скролла обратно наверх.</li></ul><p>Мастер может гибко добавлять и менять местами модульные блоки описания:</p><ul><li><strong>Вводный лид:</strong> краткое эмоциональное описание назначения предмета крупным шрифтом.</li><li><strong>Сетка преимуществ:</strong> карточки с иконками, раскрывающие технологические особенности.</li><li><strong>История создания:</strong> рассказ о подборе сырья, ручной формовке или авторской обработке.</li><li><strong>Видео-демонстрация:</strong> адаптер с облегченным фасадом для роликов из ВКонтакте, Рутуба или Ютуба. До первого клика внешние скрипты не загружаются, экономя трафик и ускоряя открытие сайта.</li><li><strong>Спецификация:</strong> строгая таблица характеристик (габариты, сорт кожи, фурнитура, масса).</li><li><strong>Частые вопросы (FAQ):</strong> раскрывающиеся аккордеоны с ответами об уходе за изделием и сроках гарантии.</li></ul><h3 id="_3-каналы-связи-чекаут-и-правовои-контур" tabindex="-1">3. Каналы связи, чекаут и правовой контур <a class="header-anchor" href="#_3-каналы-связи-чекаут-и-правовои-контур" aria-label="Permalink to &quot;3. Каналы связи, чекаут и правовой контур&quot;">​</a></h3><p>Программа поддерживает три независимых режима приема заявок:</p><ol><li><strong>Прямые диалоги в мессенджерах:</strong> покупатель нажимает на кнопку и сразу переходит в чат с мастером в Телеграм или Ватсап с автоматически сформированным списком выбранных изделий и итоговой суммой. Идеально для штучного крафта и кастомных заказов.</li><li><strong>Локальный скрипт обработки заявок (<code>order.php</code>):</strong> при публикации на классическом PHP-хостинге компилятор создает компактный скрипт. Он принимает заявку, проверяет невидимую спам-ловушку (Honeypot), защищает сервер от флуда и пересылает заказ вам в мессенджер через официальный бот.</li><li><strong>Российские формы заявок:</strong> встроенная интеграция с сервисом Яндекс Формы для надежного сбора контактов.</li></ol><div class="info custom-block"><p class="custom-block-title">Защита персональных данных (152-ФЗ РФ и GDPR)</p><p>Встроенный генератор правовых страниц автоматически формирует текст Политики конфиденциальности и Пользовательского соглашения с подстановкой ИНН, названия мастерской и города. В форму оформления заказа внедрен обязательный пункт согласия на обработку данных со ссылкой на документ.</p></div><hr><h2 id="пошаговое-руководство-по-запуску" tabindex="-1">Пошаговое руководство по запуску <a class="header-anchor" href="#пошаговое-руководство-по-запуску" aria-label="Permalink to &quot;Пошаговое руководство по запуску&quot;">​</a></h2><h3 id="шаг-1-настроика-профиля-и-разделов" tabindex="-1">Шаг 1. Настройка профиля и разделов <a class="header-anchor" href="#шаг-1-настроика-профиля-и-разделов" aria-label="Permalink to &quot;Шаг 1. Настройка профиля и разделов&quot;">​</a></h3><ol><li>Перейдите во вкладку <strong>«Витрина»</strong> → подвкладка <strong>«Профиль и стиль»</strong>.</li><li>В вертикальном сайдбаре перейдите в раздел <strong>«Общие данные»</strong>: укажите название мастерской, слоган, город и контакты.</li><li>В разделе <strong>«Главная страница»</strong> задайте текст торгового предложения и загрузите фотографию для блока «Слово мастера».</li><li>В разделе <strong>«Оплата и доставка»</strong> настройте тарифы курьерской доставки, самовывоза и пересылки транспортными компаниями.</li><li>В разделе <strong>«Юридические данные»</strong> укажите реквизиты ИП или самозанятого и нажмите кнопку <strong>«Сгенерировать политику 152-ФЗ»</strong>.</li><li>В разделе <strong>«Тема оформления»</strong> выберите режим по умолчанию (Авто, Светлая или Тёмная) и нажмите кнопку <strong>«Сохранить профиль»</strong>.</li></ol><h3 id="шаг-2-подготовка-изделии-к-показу" tabindex="-1">Шаг 2. Подготовка изделий к показу <a class="header-anchor" href="#шаг-2-подготовка-изделии-к-показу" aria-label="Permalink to &quot;Шаг 2. Подготовка изделий к показу&quot;">​</a></h3><ol><li>Откройте подвкладку <strong>«Каталог витрины»</strong>.</li><li>Выберите удобный режим отображения в правом углу панели управления: <ul><li><strong>Сетка 3:4:</strong> наглядные вертикальные карточки изделий с обложкой в классической портретной пропорции, маркетинговыми бейджами («Хит», «Новинка») и плашкой статуса публикации.</li><li><strong>Компактный реестр:</strong> плотный табличный список с миниатюрами для быстрой ревизии большого ассортимента.</li></ul></li><li>Включите переключатель <strong>«Опубликовать»</strong> у изделий, которые должны появиться на сайте (переключатель доступен прямо на обложке карточки в сетке).</li><li>Нажмите кнопку с иконкой ползунков настройки напротив изделия: <ul><li>На вкладке <strong>«Основные параметры»</strong> задайте URL-псевдоним (slug), выберите бейдж и розничную цену для сайта.</li><li>На вкладке <strong>«Фотографии»</strong> загрузите снимки, отсортируйте порядок стрелками ◄/► и выберите обложку карточки.</li><li>На вкладке <strong>«Секции описания»</strong> добавьте преимущества, характеристики или видео-обзор изделия.</li></ul></li><li>Нажмите <strong>«Сохранить свойства товара»</strong>.</li></ol><h3 id="шаг-3-локальныи-предпросмотр-live-preview" tabindex="-1">Шаг 3. Локальный предпросмотр (Live Preview) <a class="header-anchor" href="#шаг-3-локальныи-предпросмотр-live-preview" aria-label="Permalink to &quot;Шаг 3. Локальный предпросмотр (Live Preview)&quot;">​</a></h3><p>До отправки сайта в сеть обязательно оцените его отображение:</p><ol><li>В верхней панели витрины нажмите кнопку <strong>«Предпросмотр витрины»</strong> (иконка монитора со стрелкой).</li><li>Программа запустит встроенный локальный веб-сервер и откроет витрину в вашем браузере.</li><li>Проверьте переключение тем оформления, работу фильтров каталога и оформление заказа.</li></ol><div class="warning custom-block"><p class="custom-block-title">Внимание к кэшу</p><p>Локальный сервер предпросмотра передает браузеру строгие заголовки <code>no-cache</code>, поэтому любые повторные сохранения карточек изделий отображаются сразу после обновления страницы в браузере (F5).</p></div><h3 id="шаг-4-настроика-транспорта-и-публикация" tabindex="-1">Шаг 4. Настройка транспорта и публикация <a class="header-anchor" href="#шаг-4-настроика-транспорта-и-публикация" aria-label="Permalink to &quot;Шаг 4. Настройка транспорта и публикация&quot;">​</a></h3><ol><li>Откройте подвкладку <strong>«Транспорт публикации»</strong>.</li><li>Выберите подходящий метод размещения: <ul><li><strong>Локальная папка / ZIP-архив:</strong> сохранение каталога на диск компьютера для ручного копирования.</li><li><strong>Сетевой протокол FTP:</strong> прямая выгрузка на любой виртуальный хостинг по протоколу передачи файлов.</li><li><strong>Облачное хранилище S3:</strong> прямая выгрузка в корзину Яндекс Облака или совместимых сервисов.</li><li><strong>Страницы ГитХаб:</strong> автоматическая публикация в ветку <code>gh-pages</code> через официальный интерфейс без сторонних программ.</li></ul></li><li>Нажмите кнопку <strong>«Проверить подключение»</strong>. Пароли и токены надежно защищаются аппаратным шифрованием операционной системы (DPAPI).</li><li>Нажмите <strong>«Сохранить транспорт»</strong>, а затем в верхней панели — <strong>«Опубликовать сайт»</strong>.</li></ol><hr><h2 id="обработка-входящих-заказов" tabindex="-1">Обработка входящих заказов <a class="header-anchor" href="#обработка-входящих-заказов" aria-label="Permalink to &quot;Обработка входящих заказов&quot;">​</a></h2><p>Все заказы с витрины и из социальных сетей поступают в подвкладку <strong>«Стол заказов»</strong>:</p><ol><li><strong>Заказы с сайта:</strong> приходят автоматически с сохранением состава корзины, контактов покупателя и выбранного способа доставки.</li><li><strong>Заказы из чатов Авито и мессенджеров:</strong> скопируйте текст переписки в буфер обмена и нажмите кнопку <strong>«Умная вставка»</strong>. Программа сама извлечет имя клиента, телефон, адрес доставки и артикулы изделий.</li><li><strong>Быстрые ответы клиентам:</strong> кнопка <strong>«Ответить»</strong> открывает готовые варианты сообщений («Заказ принят», «Готовим к отправке», «Реквизиты») с моментальным переходом в чат мессенджера.</li><li><strong>Списание со склада в один клик:</strong> после отправки посылки нажмите <strong>«Провести продажу»</strong>. Программа автоматически спишет партии готовой продукции со склада по методу ФИФО и зафиксирует выручку в кассе ДДС.</li></ol>',38)])])}const u=l(s,[["render",i]]);export{p as __pageData,u as default};
